#![cfg(feature = "moderation-variations-provider")]
//! Contract and actual-source replay for the retired OpenRouter application
//! attribution constant. Native Fish, Kokoro, variation and semantic callers
//! share [`OPENROUTER_APP_HEADERS`]; this suite owns no HTTP client or policy.
//!
//! The ordinary test is self-contained. The ignored replay consumes an
//! independently hashed oracle generated by the parent from the archived
//! TypeScript module under pinned Node 24.22.1 and TypeScript 5.9.3.
use dima_rust::utils::openrouter_attribution::OPENROUTER_APP_HEADERS;
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::{
    env, fs,
    path::{Path, PathBuf},
};

const SOURCE_LOGICAL: &str = "src/utils/ai/openrouter/app_attribution.util.ts";
const SOURCE_SHA256: &str = "0073e0b48172fc7ccc449fb6c47e1bcd4ffe39549d6641d32b1d0718a6e01c0c";
const NATIVE_SOURCE: &str = "src/utils/ai/openrouter/app_attribution.util.rs";
const READER: &str = "tests/fixtures/openrouter_attribution_reference.cjs";
const HELPER: &str = "tests/fixtures/openrouter_attribution_source.cjs";
const ARCHIVE_RELATIVE: &str = "archives/dimabot-typescript/2026-10-28";
const NODE_VERSION: &str = "24.22.1";
const NODE_SHA256: &str = "569128f3066ac7be59b10b9a0adef708def642ee37cbf9d560a9bdb68f872108";
const TYPESCRIPT_VERSION: &str = "5.9.3";

fn digest(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}
/// Tagged UTF-16 code units, matching the lossless source-fixture projection.
fn code_units(value: &Value) -> Vec<u16> {
    value
        .as_array()
        .expect("tagged UTF-16 array")
        .iter()
        .map(|unit| u16::try_from(unit.as_u64().expect("code unit")).expect("u16 code unit"))
        .collect()
}
fn text_units(text: &str) -> Vec<u16> {
    text.encode_utf16().collect()
}
fn hex_pin(pin: &str) {
    assert_eq!(pin.len(), 64, "expected SHA-256 hex length");
    assert!(
        pin.bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)),
        "expected lowercase SHA-256 hex"
    );
}

#[test]
fn native_constant_keeps_the_four_ordered_application_headers() {
    let expected = [
        ("HTTP-Referer", "https://domdimabot.com"),
        ("X-OpenRouter-Title", "DomDimaBot"),
        (
            "X-OpenRouter-Description",
            "DomDimaBot is a Twitch chat bot that helps make streams more engaging and fun.",
        ),
        ("X-OpenRouter-Categories", "general-chat, roleplay"),
    ];
    assert_eq!(OPENROUTER_APP_HEADERS.len(), expected.len());
    for (actual, expected) in OPENROUTER_APP_HEADERS.iter().zip(expected) {
        assert_eq!(*actual, expected);
    }
    let mut names = OPENROUTER_APP_HEADERS
        .iter()
        .map(|(name, _)| *name)
        .collect::<Vec<_>>();
    names.sort_unstable();
    names.dedup();
    assert_eq!(
        names.len(),
        OPENROUTER_APP_HEADERS.len(),
        "distinct header names"
    );
}

#[test]
#[ignore = "independently hashed actual-source constant fixture"]
fn archived_source_constant_matches_the_native_constant() {
    let path = env::var("DIMA_OPENROUTER_ATTRIBUTION_REFERENCE")
        .expect("independent source-reference path");
    let pin = env::var("DIMA_OPENROUTER_ATTRIBUTION_REFERENCE_SHA256")
        .expect("independent source-reference checksum");
    hex_pin(pin.as_str());
    assert!(
        Path::new(&path).is_absolute(),
        "reference path must be absolute"
    );
    let real = fs::canonicalize(&path).expect("reference fixture exists");
    let workspace =
        fs::canonicalize(Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap()).unwrap();
    assert!(
        !real.starts_with(&workspace),
        "reference fixture must be external"
    );
    let bytes = fs::read(&real).unwrap();
    assert!(!bytes.is_empty(), "reference fixture must not be empty");
    assert_eq!(digest(&bytes), pin, "reference checksum");
    let reference: Value = serde_json::from_slice(&bytes).unwrap();
    assert_eq!(reference["schema"].as_u64(), Some(1));

    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let repo = manifest_dir.parent().unwrap();
    let provenance = &reference["provenance"];
    let archived_relative = format!("{ARCHIVE_RELATIVE}/{SOURCE_LOGICAL}");
    assert_eq!(provenance["source"]["logical"], SOURCE_LOGICAL);
    assert_eq!(provenance["source"]["sha256"], SOURCE_SHA256);
    assert_eq!(provenance["source"]["provenance"], archived_relative);
    assert_eq!(provenance["source"]["resolvedPath"], archived_relative);
    assert_eq!(provenance["native"]["path"], NATIVE_SOURCE);
    assert_eq!(
        provenance["native"]["sha256"],
        digest(&fs::read(manifest_dir.join(NATIVE_SOURCE)).unwrap()),
        "native constant source"
    );
    assert_eq!(provenance["reader"]["path"], READER);
    assert_eq!(
        provenance["reader"]["sha256"],
        digest(&fs::read(manifest_dir.join(READER)).unwrap()),
        "source reader"
    );
    assert_eq!(provenance["helper"]["path"], HELPER);
    assert_eq!(
        provenance["helper"]["sha256"],
        digest(&fs::read(manifest_dir.join(HELPER)).unwrap()),
        "shared source resolver"
    );
    assert_eq!(provenance["toolchain"]["node"], NODE_VERSION);
    assert_eq!(provenance["toolchain"]["nodeSha256"], NODE_SHA256);
    assert_eq!(provenance["toolchain"]["typescript"], TYPESCRIPT_VERSION);
    assert_eq!(
        provenance["toolchain"]["typescriptImplementationSha256"],
        "3ae902c92cc44dace175c0e69e13a4b0899f6983c6121d76b9ab8dd5795e7675"
    );

    let manifest_file = repo.join(ARCHIVE_RELATIVE).join("manifest.json");
    let manifest_bytes = fs::read(&manifest_file).unwrap();
    assert_eq!(
        provenance["archiveManifest"]["path"],
        format!("{ARCHIVE_RELATIVE}/manifest.json")
    );
    assert_eq!(
        provenance["archiveManifest"]["sha256"],
        digest(&manifest_bytes),
        "archive manifest"
    );
    let manifest: Value = serde_json::from_slice(&manifest_bytes).unwrap();
    let entries = manifest["files"]
        .as_array()
        .expect("archive manifest files");
    assert_eq!(
        provenance["archiveManifest"]["entries"].as_u64(),
        Some(entries.len() as u64)
    );
    assert_eq!(
        provenance["source"]["archiveEntries"].as_u64(),
        Some(entries.len() as u64)
    );
    assert!(
        matches!(fs::symlink_metadata(manifest_dir.join(SOURCE_LOGICAL)), Err(error) if error.kind() == std::io::ErrorKind::NotFound),
        "retired source must be absent"
    );
    let retired = entries
        .iter()
        .filter(|entry| entry.get("source").and_then(Value::as_str) == Some(SOURCE_LOGICAL))
        .collect::<Vec<_>>();
    assert_eq!(retired.len(), 1, "exactly one archive entry");
    assert_eq!(retired[0]["sha256"], SOURCE_SHA256);
    let archived = repo.join(ARCHIVE_RELATIVE).join(SOURCE_LOGICAL);
    assert!(
        fs::symlink_metadata(&archived)
            .unwrap()
            .file_type()
            .is_file(),
        "archived source must be a regular file"
    );
    assert_eq!(
        digest(&fs::read(&archived).unwrap()),
        SOURCE_SHA256,
        "archived source bytes"
    );

    let module = &reference["module"];
    assert_eq!(module["logical"], SOURCE_LOGICAL);
    assert_eq!(module["statementCount"].as_u64(), Some(1));
    assert_eq!(module["imports"], Value::Array(Vec::new()));
    assert_eq!(module["declaration"], "OPENROUTER_APP_HEADERS");
    assert_eq!(module["asConstType"], "const");
    let fields = module["fields"].as_array().expect("ordered source fields");
    assert_eq!(fields.len(), OPENROUTER_APP_HEADERS.len());
    for (index, (field, (name, value))) in fields.iter().zip(OPENROUTER_APP_HEADERS).enumerate() {
        assert_eq!(field["index"].as_u64(), Some(index as u64));
        assert_eq!(field["name"], *name);
        assert_eq!(field["value"], *value);
        assert_eq!(field["nameKind"], "StringLiteral");
        assert_eq!(field["valueKind"], "StringLiteral");
    }

    let constants = &reference["constants"];
    let entries = constants["fields"].as_array().expect("constant entries");
    assert_eq!(entries.len(), OPENROUTER_APP_HEADERS.len());
    for (entry, (name, value)) in entries.iter().zip(OPENROUTER_APP_HEADERS) {
        assert_eq!(code_units(&entry["name"]), text_units(name));
        assert_eq!(code_units(&entry["value"]), text_units(value));
    }
    let wire = format!(
        "{{{}}}",
        OPENROUTER_APP_HEADERS
            .iter()
            .map(|(name, value)| format!(
                "{}:{}",
                serde_json::to_string(name).unwrap(),
                serde_json::to_string(value).unwrap()
            ))
            .collect::<Vec<_>>()
            .join(",")
    );
    assert_eq!(
        code_units(&constants["wire"]),
        text_units(&wire),
        "ordered JSON wire projection"
    );
}
